{
  "root": "root_column",
  "state": {
    "games": [
      {
        "id": "codenames",
        "title": "Codenames",
        "category": "Party",
        "time": "15 Minutes",
        "description": "The group splits into two teams, Red and Blue. Each team has a Spymaster who provides one-word clues linked to multiple cards on the table. The goal is for teammates to guess the correct words based on the clue without picking the opposing team's words or the instant-loss Assassin card. It encourages clever thinking and group discussion.",
        "url": "https://boardgamegeek.com/boardgame/178900/codenames"
      },
      {
        "id": "just_one",
        "title": "Just One",
        "category": "Party",
        "time": "20 Minutes",
        "description": "This is a fully cooperative game where everyone wins or loses together. One player is the guesser, and the other five write one-word clues to help them guess a specific word. The catch is that if any two players write the exact same clue, those clues are erased and the guesser never sees them. It forces players to be creative rather than obvious.",
        "url": "https://boardgamegeek.com/boardgame/254640/just-one"
      },
      {
        "id": "deception",
        "title": "Deception: Murder in Hong Kong",
        "category": "Social Deduction",
        "time": "20 Minutes",
        "description": "One player is secretly the Murderer, and another is the Forensic Scientist who knows the solution but can only communicate by placing markers on scene tiles (like Cause of Death: Suffocation). The remaining players are investigators trying to interpret these vague clues to identify the murderer and the weapon used. It is less aggressive than other lying games because the focus is on the evidence.",
        "url": "https://boardgamegeek.com/boardgame/156129/deception-murder-in-hong-kong"
      },
      {
        "id": "resistance",
        "title": "The Resistance",
        "category": "Social Deduction",
        "time": "30 Minutes",
        "description": "Players are members of a resistance group trying to overthrow a government, but spies have infiltrated the ranks. In each round, a leader proposes a team to go on a mission. Everyone votes to approve the team. If the mission goes ahead, players on the team secretly choose to Support or Sabotage the mission. The goal is to deduce who the saboteurs are based on voting patterns and mission results.",
        "url": "https://boardgamegeek.com/boardgame/41114/the-resistance"
      }
    ]
  },
  "elements": {
    "root_column": {
      "type": "Column",
      "props": {
        "spacing": "medium",
        "padding": {
          "all": "medium"
        }
      },
      "children": [
        "title_text",
        "intro_card",
        "picks_title",
        "games_list",
        "actions_title",
        "actions_row"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Beginner-Friendly 6-Player Game Recommendations",
        "style": "headline"
      },
      "children": []
    },
    "intro_card": {
      "type": "Card",
      "props": {},
      "children": [
        "intro_column"
      ]
    },
    "intro_column": {
      "type": "Column",
      "props": {
        "spacing": "small",
        "padding": {
          "all": "medium"
        }
      },
      "children": [
        "intro_title",
        "intro_text"
      ]
    },
    "intro_title": {
      "type": "Text",
      "props": {
        "text": "Group Dynamics and Selection Criteria",
        "style": "title"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "These recommendations assume the group has little to no prior experience with modern hobby board games. The selections focus on high interaction, minimal downtime between turns, and rules that can be taught in under 5 minutes. The games selected bridge the gap between casual conversation and structured play, ensuring the 60-minute time limit is respected even with teaching time included.",
        "style": "body"
      },
      "children": []
    },
    "picks_title": {
      "type": "Text",
      "props": {
        "text": "Top Party and Deduction Picks",
        "style": "headline-small"
      },
      "children": []
    },
    "games_list": {
      "type": "List",
      "props": {
        "spacing": "medium",
        "repeat": {
          "statePath": "/games",
          "key": "id"
        }
      },
      "children": [
        "game_card_template"
      ]
    },
    "game_card_template": {
      "type": "Card",
      "props": {},
      "children": [
        "game_column"
      ]
    },
