      "type": "Column",
      "props": {
        "spacing": "medium",
        "padding": {
          "all": "medium"
        }
      },
      "children": [
        "game_title",
        "game_meta_row",
        "game_description",
        "game_button"
      ]
    },
    "game_title": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "title"
        },
        "style": "title"
      },
      "children": []
    },
    "game_meta_row": {
      "type": "Row",
