          "$item": "description"
        },
        "style": "body"
      },
      "children": []
    },
    "game_button": {
      "type": "Button",
      "props": {
        "label": "View on BoardGameGeek",
        "variant": "outlined"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "url": {
            "$item": "url"
          }
        }
      }
    },
    "actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "style": "headline-small"
      },
      "children": []
    },
    "actions_row": {
      "type": "Row",
      "props": {
        "distribution": "space-evenly",
        "spacing": "medium"
      },
      "children": [
        "party_button",
        "deduction_button"
      ]
    },
    "party_button": {
      "type": "Button",
      "props": {
        "label": "Browse Top Party Games"
      },
      "children": [],
